import base64
import io
from PIL import Image

embedded_image_data = b'' 

# Function to decode the base64 data back into an image
def get_embedded_image(base64_bytes):
    image_bytes = base64.b64decode(base64_bytes)
    # Use Pillow (PIL) to open the image from bytes
    image = Image.open(io.BytesIO(image_bytes))
    return image

def get_datascratch_logo():
    return get_embedded_image(embedded_image_data)